        self.assertIsInstance(
            self.verdict(unowned, ("thread-1: ThreadLive",)), codex_mesh.ServerInUse
        )
        self.assertIsInstance(
            self.verdict(dataclasses.replace(unowned, age_secs=10.0)), codex_mesh.ServerInUse
        )

